#!/usr/bin/env python3
import json
import os
import sys

# Paths
TOKENS_FILE = "/app/tokens.json"
API_BASE_URL = "http://localhost:5000"

def load_tokens():
    """Load tokens from /app/tokens.json"""
    if os.path.exists(TOKENS_FILE):
        with open(TOKENS_FILE, 'r') as f:
            return json.load(f)
    return None

def save_tokens(access_token, refresh_token, jti):
    """Save tokens to /app/tokens.json"""
    data = {
        "access_token": access_token,
        "refresh_token": refresh_token,
        "jti": jti
    }
    with open(TOKENS_FILE, 'w') as f:
        json.dump(data, f)

def acquire():
    """Login and acquire tokens, save to /app/tokens.json"""
    import requests
    try:
        response = requests.post(f"{API_BASE_URL}/auth/login", json={
            "username": "admin",
            "password": "password123"
        })
        if response.status_code == 200:
            data = response.json()
            save_tokens(data['access_token'], data['refresh_token'], data['jti'])
            print("Tokens acquired successfully!")
            print(f"JTI: {data['jti']}")
            print(f"Access token: {data['access_token'][:20]}...")
            print(f"Refresh token: {data['refresh_token'][:20]}...")
        else:
            print(f"Failed to acquire tokens: {response.text}")
            return False
    except Exception as e:
        print(f"Error during acquire: {e}")
        return False
    return True

def validate():
    """Validate a token from /app/tokens.json"""
    import requests
    tokens = load_tokens()
    if not tokens:
        print("No tokens found in /app/tokens.json")
        return False

    access_token = tokens.get('access_token')
    if not access_token:
        print("No valid token data found")
        return False

    # Validate using API
    headers = {"Authorization": f"Bearer {access_token}"}
    response = requests.get(f"{API_BASE_URL}/auth/validate", headers=headers)
    if response.status_code == 200:
        data = response.json()
        print("Token is valid!")
        print(json.dumps(data, indent=2))
        return True
    elif response.status_code == 401:
        print("Token is expired or invalid")
    elif response.status_code == 403:
        print("Token has been revoked")
    else:
        print(f"Validation failed: {response.text}")
    return False

def revoke():
    """Revoke a token and update /app/tokens.json"""
    import requests
    tokens = load_tokens()
    if not tokens:
        print("No tokens found in /app/tokens.json")
        return False

    token = tokens.get('access_token')
    if not token:
        print("No access token found in tokens.json")
        return False

    try:
        response = requests.post(f"{API_BASE_URL}/auth/revoke", json={"token": token})
        if response.status_code == 200:
            print("Token revoked successfully!")
            # Update tokens.json - remove the access token but keep refresh token
            if tokens.get('refresh_token'):
                new_data = {
                    "access_token": None,  # Mark access as revoked/removed
                    "refresh_token": tokens['refresh_token'],
                    "jti": tokens['jti']
                }
                with open(TOKENS_FILE, 'w') as f:
                    json.dump(new_data, f)
                print("tokens.json updated (access_token removed)")
            else:
                # If no refresh token, just delete the file or keep empty
                os.remove(TOKENS_FILE)
                print("tokens.json deleted")
            return True
        else:
            print(f"Revoke failed: {response.text}")
            return False
    except Exception as e:
        print(f"Error during revoke: {e}")
        return False

def retry():
    """Retry acquiring tokens if expired"""
    print("Retrying token acquisition...")
    acquire()

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python cli.py <command>")
        print("Commands: acquire, validate, revoke, retry")
        sys.exit(1)

    command = sys.argv[1]
    if command == "acquire":
        acquire()
    elif command == "validate":
        validate()
    elif command == "revoke":
        revoke()
    elif command == "retry":
        retry()
    else:
        print("Unknown command. Use: acquire, validate, revoke, retry")
        sys.exit(1)

